#!/usr/bin/env python3
"""Audit existing WebP files and match candidate images to the single Shop catalogue.
Pillow is an authoring/test dependency only; this does not download or alter images.
"""
from pathlib import Path
from urllib.parse import quote
import argparse,hashlib,json
ROOT=Path(__file__).resolve().parents[1]
def inventory():
 from PIL import Image
 products=json.loads((ROOT/'_data/shop-products.json').read_text())['products']
 candidates={i['src'].lstrip('/'):p for p in products for i in p.get('images',[]) if p.get('candidateEvidence')}
 refs=json.loads((ROOT/'_data/collection-designs.json').read_text())['designs'];rows=[]
 for path in sorted(ROOT.rglob('*.webp')):
  if '.git' in path.parts:continue
  rel=path.relative_to(ROOT).as_posix();p=candidates.get(rel);sha=hashlib.sha256(path.read_bytes()).hexdigest()
  matches=[x['id'] for x in products if any(i['src'].lstrip('/')==rel or x.get('candidateEvidence',{}).get('imageSha256')==sha for i in x.get('images',[]))]
  role='candidate' if p else 'optimised derivative/supporting website asset' if rel.startswith('assets/') else 'service hero' if rel.startswith('hero-') else 'illustrative fabric guide' if rel.startswith('fabric-') else 'measurement guide' if path.name in ['belly.webp','bicep.webp','chest.webp','hip.webp','jacket length.webp','neck.jepg.webp','neck.webp','shoulder.webp','sleeve length.webp','thigh.webp','trauser length.webp','waist.webp'] else 'unclassified root WebP — review'
  try:
   with Image.open(path) as image:image.load();width,height=image.size
   decoded=True;error=None
  except Exception as exc:decoded=False;width=height=None;error=type(exc).__name__
  rows.append({'filename':path.name,'path':'/'+rel,'sha256':sha,'bytes':path.stat().st_size,'width':width,'height':height,'decoded':decoded,'error':error,'role':role,'proposedProductName':p['name'] if p else None,'proposedCategory':p['category'] if p else None,'matchedShopIds':matches,'publishedShopIds':[x['id'] for x in products if x['id'] in matches and x['publicationStatus']=='published'],'existingSuitReferenceIds':[r['id'] for r in refs if any(i['src']=='/'+rel for i in r['images'])],'missingInformation':p.get('missingInformation',[]) if p else []})
 return rows

def outputs():
 rows=inventory();c=[r for r in rows if r['role']=='candidate'];groups={}
 for r in rows:groups.setdefault(r['sha256'],[]).append(r['path'])
 duplicates=[v for v in groups.values() if len(v)>1]
 result={'schemaVersion':1,'baselineCommit':'626ccd8145c282a2732922d44646387d681c2a55','scope':'All repository WebP files, including supporting derivatives; not all are merchandise. Image inspection does not establish sale approval.','totals':{'webpFiles':len(rows),'decoded':sum(r['decoded'] for r in rows),'candidateImages':len(c),'supportingOrExcluded':len(rows)-len(c),'publishedShopProducts':len({i for r in c for i in r['publishedShopIds']})},'exactDuplicateGroups':duplicates,'images':rows}
 text='# Shop product-image inventory — 6 November 2026\n\nGenerated by `python3 scripts/inventory_shop_images.py`; no external images or image modification.\n\n'+f"{len(rows)} WebP files decoded/audited; {len(c)} candidate images. Remaining images are guide/hero/derivative assets, not new merchandise. Zero products are approved for Shop publication.\n\n"+'The filenames describe images, not verified materials, pack quantities, stock or sale conditions. Proposed IDs are technical draft identifiers, not owner-approved SKUs. Composite/overlapping references require identity review. Existing suit-reference approval does not automatically approve merchandise.\n\n| Original filename | Image location | Proposed product | Proposed category | Decodes | Catalogue draft | Existing suit reference | Missing information |\n|---|---|---|---|---|---|---|---|\n'
 for r in c:
  text+='| '+r['filename']+' | [View](../'+quote(r['path'].lstrip('/'),safe='/')+') | '+r['proposedProductName']+' | '+r['proposedCategory']+' | '+('PASS' if r['decoded'] else 'FAIL')+' | '+', '.join(r['matchedShopIds'])+' | '+(', '.join(r['existingSuitReferenceIds']) or 'None')+' | '+'; '.join(r['missingInformation'])+' |\n'
 text+='\n## Exact duplicate assets\n'+''.join('- '+'; '.join(v)+'\n' for v in duplicates)+'\nThese are file-byte duplicates, not inferred product identities. The duplicate neck photographs are measurement assets and are excluded from merchandise. See the JSON audit for all supporting/excluded files and dimensions.\n'
 return {ROOT/'_data/shop-image-inventory.json':json.dumps(result,indent=2,ensure_ascii=False)+'\n',ROOT/'docs/shop-product-image-inventory.md':text}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
 for path,value in outputs().items():
  if args.check:assert path.is_file() and path.read_text()==value,'Stale image inventory: '+str(path)
  else:path.write_text(value)
 print('PASS existing WebP inventory '+('synchronized' if args.check else 'generated'))
